import { createServer } from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

const assets = new Map([
  ['/', ['text/html; charset=utf-8', readFileSync(new URL('./public/index.html', import.meta.url))]],
  ['/app.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./public/app.js', import.meta.url))]],
  ['/style.css', ['text/css; charset=utf-8', readFileSync(new URL('./public/style.css', import.meta.url))]],
]);

function json(response, status, data) {
  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(data));
}

async function readJson(request) {
  let body = '';
  for await (const chunk of request) {
    body += chunk;
    if (Buffer.byteLength(body) > 64 * 1024) {
      const error = new Error('Request is too large');
      error.status = 413;
      throw error;
    }
  }
  try {
    return JSON.parse(body);
  } catch {
    const error = new Error('Invalid JSON');
    error.status = 400;
    throw error;
  }
}

export function createApplication(dbPath = process.env.DB_PATH || './data/workboard.sqlite') {
  if (dbPath !== ':memory:') mkdirSync(dirname(resolve(dbPath)), { recursive: true });
  const database = new DatabaseSync(dbPath);
  database.exec(`
    PRAGMA foreign_keys = ON;
    CREATE TABLE IF NOT EXISTS projects (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL CHECK (length(trim(name)) > 0)
    );
    CREATE TABLE IF NOT EXISTS tasks (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      project_id INTEGER NOT NULL REFERENCES projects(id),
      title TEXT NOT NULL CHECK (length(trim(title)) > 0),
      completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
    );
    CREATE INDEX IF NOT EXISTS tasks_project_id ON tasks(project_id, id);
  `);
  // Migrate existing project databases without changing IDs or task ownership.
  if (!database.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'archived')) {
    database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
  }
  const projectSelect = `SELECT p.id, p.name, p.archived,
    (SELECT COUNT(*) FROM tasks WHERE project_id = p.id) AS total,
    (SELECT COUNT(*) FROM tasks WHERE project_id = p.id AND completed = 1) AS completed
    FROM projects p`;
  const listProjects = database.prepare(`${projectSelect} ORDER BY p.id`);
  const getProject = database.prepare(`${projectSelect} WHERE p.id = ?`);
  const updateProject = database.prepare('UPDATE projects SET archived = ? WHERE id = ?');
  const projectData = (project) => ({ ...project, archived: Boolean(project.archived) });
  const insertProject = database.prepare('INSERT INTO projects (name) VALUES (?)');
  const listTasks = database.prepare('SELECT id, title, completed FROM tasks WHERE project_id = ? ORDER BY id');
  const getTask = database.prepare('SELECT id, title, completed FROM tasks WHERE project_id = ? AND id = ?');
  const insertTask = database.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)');
  const updateTask = database.prepare('UPDATE tasks SET completed = ? WHERE project_id = ? AND id = ?');
  const taskData = (task) => ({ ...task, completed: Boolean(task.completed) });

  const server = createServer(async (request, response) => {
    try {
      const pathname = new URL(request.url, 'http://localhost').pathname;
      if (request.method === 'GET' && pathname === '/health') {
        return json(response, 200, { status: 'ok' });
      }
      if (pathname === '/api/projects') {
        if (request.method === 'GET') return json(response, 200, listProjects.all().map(projectData));
        if (request.method === 'POST') {
          const input = await readJson(request);
          const name = typeof input?.name === 'string' ? input.name.trim() : '';
          if (!name) return json(response, 400, { error: 'Project name is required' });
          const result = insertProject.run(name);
          return json(response, 201, projectData(getProject.get(Number(result.lastInsertRowid))));
        }
      }
      const tasksApi = pathname.match(/^\/api\/projects\/([1-9]\d*)\/tasks(?:\/([1-9]\d*))?$/);
      if (tasksApi) {
        const projectId = Number(tasksApi[1]);
        const taskId = tasksApi[2] ? Number(tasksApi[2]) : null;
        const project = getProject.get(projectId);
        if (!project) return json(response, 404, { error: 'Project not found' });
        if (!taskId && request.method === 'GET') {
          return json(response, 200, listTasks.all(projectId).map(taskData));
        }
        if (!taskId && request.method === 'POST') {
          const input = await readJson(request);
          const title = typeof input?.title === 'string' ? input.title.trim() : '';
          if (!title) return json(response, 400, { error: 'Task title is required' });
          if (getProject.get(projectId).archived) return json(response, 409, { error: 'Archived project is read-only' });
          const result = insertTask.run(projectId, title);
          return json(response, 201, taskData(getTask.get(projectId, Number(result.lastInsertRowid))));
        }
        if (taskId && request.method === 'PATCH') {
          if (!getTask.get(projectId, taskId)) return json(response, 404, { error: 'Task not found' });
          const input = await readJson(request);
          if (typeof input?.completed !== 'boolean') {
            return json(response, 400, { error: 'Completion must be a boolean' });
          }
          if (getProject.get(projectId).archived) return json(response, 409, { error: 'Archived project is read-only' });
          updateTask.run(Number(input.completed), projectId, taskId);
          return json(response, 200, taskData(getTask.get(projectId, taskId)));
        }
      }
      const projectApi = pathname.match(/^\/api\/projects\/([1-9]\d*)$/);
      if (projectApi) {
        const id = Number(projectApi[1]);
        const project = getProject.get(id);
        if (!project) return json(response, 404, { error: 'Project not found' });
        if (request.method === 'GET') return json(response, 200, projectData(project));
        if (request.method === 'PATCH') {
          const input = await readJson(request);
          if (typeof input?.archived !== 'boolean') {
            return json(response, 400, { error: 'Archived must be a boolean' });
          }
          updateProject.run(Number(input.archived), id);
          return json(response, 200, projectData(getProject.get(id)));
        }
      }
      if (request.method === 'GET') {
        const asset = assets.get(/^\/projects\/[1-9]\d*$/.test(pathname) ? '/' : pathname);
        if (asset) {
          response.writeHead(200, { 'Content-Type': asset[0] });
          return response.end(asset[1]);
        }
      }
      json(response, 404, { error: 'Not found' });
    } catch (error) {
      if (!error.status) console.error(error);
      json(response, error.status || 500, { error: error.status ? error.message : 'Internal server error' });
    }
  });
  server.on('close', () => database.close());
  return server;
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  const server = createApplication();
  const port = Number(process.env.PORT ?? 8080);
  server.listen(port, '0.0.0.0', () => {
    console.log(`Workboard listening on port ${server.address().port}`);
  });
  for (const signal of ['SIGINT', 'SIGTERM']) {
    process.on(signal, () => server.close());
  }
}

const listView = document.querySelector('#project-list');
const detailView = document.querySelector('#project-detail');
const projects = document.querySelector('#projects');
const form = document.querySelector('#create-project');
const nameInput = document.querySelector('#project-name');
const alert = document.querySelector('#error');
const taskForm = document.querySelector('#create-task');
const taskTitleInput = document.querySelector('#task-title');
const taskFilter = document.querySelector('#task-filter');
const taskList = document.querySelector('#tasks');
const projectFilter = document.querySelector('#project-filter');
let projectId;
let archived = false;
let projectData = [];
let tasks = [];

function showError(message) {
  alert.textContent = message;
  alert.hidden = !message;
}

async function request(path, options) {
  const response = await fetch(path, options);
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || 'Unable to complete request');
  return data;
}

function appendProject(project) {
  const row = document.createElement('div');
  row.dataset.testid = 'project-row';
  row.className = 'project-row';
  const name = document.createElement('span');
  name.textContent = project.name;
  const open = document.createElement('button');
  open.type = 'button';
  open.textContent = 'Open project';
  open.addEventListener('click', () => { window.location.href = `/projects/${project.id}`; });
  const summary = document.createElement('span');
  summary.dataset.testid = 'project-summary';
  summary.textContent = `${project.completed}/${project.total} completed`;
  const archive = document.createElement('button');
  archive.type = 'button';
  archive.textContent = project.archived ? 'Restore project' : 'Archive project';
  archive.addEventListener('click', async () => {
    archive.disabled = true;
    showError('');
    try {
      const saved = await request(`/api/projects/${project.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ archived: !project.archived }),
      });
      Object.assign(project, saved);
      renderProjects();
    } catch (error) {
      showError(error.message);
    } finally {
      archive.disabled = false;
    }
  });
  row.append(name, summary, open, archive);
  projects.append(row);
}

function renderProjects() {
  projects.replaceChildren();
  for (const project of projectData) {
    if (project.archived === (projectFilter.value === 'archived')) appendProject(project);
  }
}

projectFilter.addEventListener('change', renderProjects);

form.addEventListener('submit', async (event) => {
  event.preventDefault();
  showError('');
  const name = nameInput.value.trim();
  if (!name) return showError('Project name is required');
  const button = form.querySelector('button');
  button.disabled = true;
  try {
    const project = await request('/api/projects', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name }),
    });
    projectData.push(project);
    renderProjects();
    nameInput.value = '';
    nameInput.focus();
  } catch (error) {
    showError(error.message);
  } finally {
    button.disabled = false;
  }
});

document.querySelector('#back').addEventListener('click', () => { window.location.href = '/'; });

function renderTasks() {
  taskList.replaceChildren();
  for (const task of tasks) {
    if (taskFilter.value === 'open' && task.completed) continue;
    if (taskFilter.value === 'completed' && !task.completed) continue;
    const row = document.createElement('div');
    row.dataset.testid = 'task-row';
    row.className = 'task-row';
    const title = document.createElement('span');
    title.textContent = task.title;
    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.checked = task.completed;
    checkbox.disabled = archived;
    checkbox.setAttribute('aria-label', `Complete ${task.title}`);
    checkbox.addEventListener('change', async () => {
      if (archived) return;
      checkbox.disabled = true;
      showError('');
      try {
        const saved = await request(`/api/projects/${projectId}/tasks/${task.id}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ completed: checkbox.checked }),
        });
        task.completed = saved.completed;
        renderTasks();
      } catch (error) {
        checkbox.checked = task.completed;
        showError(error.message);
      } finally {
        checkbox.disabled = archived;
      }
    });
    row.append(title, checkbox);
    taskList.append(row);
  }
}

taskFilter.addEventListener('change', renderTasks);
taskForm.addEventListener('submit', async (event) => {
  event.preventDefault();
  if (archived) return;
  showError('');
  const title = taskTitleInput.value.trim();
  if (!title) return showError('Task title is required');
  const button = taskForm.querySelector('button');
  button.disabled = true;
  try {
    const task = await request(`/api/projects/${projectId}/tasks`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ title }),
    });
    tasks.push(task);
    renderTasks();
    taskTitleInput.value = '';
    taskTitleInput.focus();
  } catch (error) {
    showError(error.message);
  } finally {
    button.disabled = archived;
  }
});

async function loadPage() {
  const match = window.location.pathname.match(/^\/projects\/([1-9]\d*)$/);
  try {
    if (match) {
      detailView.hidden = false;
      const project = await request(`/api/projects/${match[1]}`);
      document.querySelector('#project-title').textContent = project.name;
      document.title = `${project.name} — Workboard`;
      projectId = project.id;
      archived = Boolean(project.archived);
      document.querySelector('#archived-notice').hidden = !archived;
      taskForm.querySelector('button').disabled = archived;
      tasks = await request(`/api/projects/${projectId}/tasks`);
      renderTasks();
    } else {
      listView.hidden = false;
      projectData = await request('/api/projects');
      renderProjects();
    }
  } catch (error) {
    showError(error.message);
  }
}

loadPage();

import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { runInNewContext } from 'node:vm';

// Minimal DOM adapter for exercising the application's browser event handlers.
class Element {
  constructor() {
    this.children = [];
    this.dataset = {};
    this.listeners = {};
    this.attributes = {};
    this.value = '';
    this.textContent = '';
  }
  append(...children) { this.children.push(...children); }
  replaceChildren() { this.children = []; }
  addEventListener(type, handler) { this.listeners[type] = handler; }
  setAttribute(name, value) { this.attributes[name] = value; }
  querySelector() { return this.button ??= new Element(); }
  focus() {}
  async trigger(type) { await this.listeners[type]({ preventDefault() {} }); }
}

const settle = () => new Promise((resolve) => setImmediate(resolve));

test('project task UI validates, filters, updates completion and rolls back errors', async () => {
  const elements = new Map();
  const element = (selector) => {
    if (!elements.has(selector)) elements.set(selector, new Element());
    return elements.get(selector);
  };
  element('#task-filter').value = 'all';
  const tasks = [
    { id: 1, title: '<b>Open task</b>', completed: false },
    { id: 2, title: 'Done task', completed: true },
  ];
  let failUpdate = false;
  let creates = 0;
  const fetch = async (path, options) => {
    let data;
    let ok = true;
    if (options?.method === 'POST') {
      creates++;
      data = { id: 3, title: JSON.parse(options.body).title, completed: false };
      tasks.push(data);
    } else if (options?.method === 'PATCH') {
      if (failUpdate) {
        ok = false;
        data = { error: 'Save failed' };
      } else {
        const task = tasks.find((task) => path.endsWith(`/${task.id}`));
        task.completed = JSON.parse(options.body).completed;
        data = task;
      }
    } else {
      data = path.endsWith('/tasks') ? tasks : { id: 7, name: 'Project' };
    }
    return { ok, json: async () => structuredClone(data) };
  };
  runInNewContext(await readFile(new URL('../public/app.js', import.meta.url), 'utf8'), {
    document: { querySelector: element, createElement: () => new Element() },
    window: { location: { pathname: '/projects/7' } },
    fetch,
  });
  await settle();
  const rows = () => element('#tasks').children;
  const titles = () => rows().map((row) => row.children[0].textContent);
  assert.deepEqual(titles(), ['<b>Open task</b>', 'Done task']);
  assert.equal(rows()[0].dataset.testid, 'task-row');
  assert.equal(rows()[0].children[1].attributes['aria-label'], 'Complete <b>Open task</b>');
  assert.equal(rows()[0].children[1].checked, false);
  assert.equal(rows()[1].children[1].checked, true);

  element('#task-title').value = ' \t ';
  await element('#create-task').trigger('submit');
  assert.equal(creates, 0);
  assert.equal(element('#error').textContent, 'Task title is required');
  element('#task-title').value = '  New task  ';
  await element('#create-task').trigger('submit');
  assert.equal(creates, 1);
  assert.deepEqual(titles(), ['<b>Open task</b>', 'Done task', 'New task']);

  element('#task-filter').value = 'open';
  await element('#task-filter').trigger('change');
  assert.deepEqual(titles(), ['<b>Open task</b>', 'New task']);
  const checkbox = rows()[0].children[1];
  checkbox.checked = true;
  await checkbox.trigger('change');
  assert.deepEqual(titles(), ['New task']);
  element('#task-filter').value = 'completed';
  await element('#task-filter').trigger('change');
  assert.deepEqual(titles(), ['<b>Open task</b>', 'Done task']);
  const completed = rows()[0].children[1];
  completed.checked = false;
  failUpdate = true;
  await completed.trigger('change');
  assert.equal(completed.checked, true);
  assert.equal(element('#error').textContent, 'Save failed');
  failUpdate = false;
  completed.checked = false;
  await completed.trigger('change');
  assert.deepEqual(titles(), ['Done task']);
  element('#task-filter').value = 'all';
  await element('#task-filter').trigger('change');
  assert.deepEqual(titles(), ['<b>Open task</b>', 'Done task', 'New task']);
});

async function loadUI(pathname, fetch) {
  const elements = new Map();
  const element = (selector) => {
    if (!elements.has(selector)) elements.set(selector, new Element());
    return elements.get(selector);
  };
  element('#project-filter').value = 'active';
  element('#task-filter').value = 'all';
  const window = { location: { pathname } };
  runInNewContext(await readFile(new URL('../public/app.js', import.meta.url), 'utf8'), {
    document: { querySelector: element, createElement: () => new Element() }, window, fetch,
  });
  await settle();
  return { element, window };
}

test('project list filters, summaries, archive, restore and navigation', async () => {
  const data = [
    { id: 1, name: 'First', archived: false, completed: 1, total: 2 },
    { id: 2, name: 'Second', archived: false, completed: 0, total: 0 },
  ];
  let fail = false;
  const { element, window } = await loadUI('/', async (path, options) => {
    if (fail) return { ok: false, json: async () => ({ error: 'Save failed' }) };
    let result = data;
    if (options?.method === 'PATCH') {
      result = data.find((project) => path.endsWith(`/${project.id}`));
      result.archived = JSON.parse(options.body).archived;
    }
    return { ok: true, json: async () => structuredClone(result) };
  });
  const rows = () => element('#projects').children;
  assert.equal(rows().length, 2);
  assert.equal(rows()[0].dataset.testid, 'project-row');
  assert.equal(rows()[0].children[1].dataset.testid, 'project-summary');
  assert.equal(rows()[0].children[1].textContent, '1/2 completed');
  assert.equal(rows()[1].children[1].textContent, '0/0 completed');
  fail = true;
  await rows()[0].children[3].trigger('click');
  assert.equal(rows().length, 2);
  assert.equal(element('#error').textContent, 'Save failed');
  fail = false;
  await rows()[0].children[3].trigger('click');
  assert.equal(rows().length, 1);
  assert.equal(rows()[0].children[0].textContent, 'Second');
  element('#project-filter').value = 'archived';
  await element('#project-filter').trigger('change');
  assert.equal(rows().length, 1);
  assert.equal(rows()[0].children[3].textContent, 'Restore project');
  await rows()[0].children[2].trigger('click');
  assert.equal(window.location.href, '/projects/1');
  await rows()[0].children[3].trigger('click');
  assert.equal(rows().length, 0);
  element('#project-filter').value = 'active';
  await element('#project-filter').trigger('change');
  assert.equal(rows().length, 2);
  assert.equal(rows()[0].children[0].textContent, 'First');
  assert.equal(rows()[0].children[1].textContent, '1/2 completed');
});

test('archived project is visibly read-only and task filtering remains usable', async () => {
  let writes = 0;
  const { element } = await loadUI('/projects/1', async (path, options) => {
    if (options) writes++;
    const data = path.endsWith('/tasks') ? [
      { id: 1, title: 'Open', completed: false },
      { id: 2, title: 'Done', completed: true },
    ] : { id: 1, name: 'Archived', archived: true };
    return { ok: true, json: async () => data };
  });
  assert.equal(element('#archived-notice').hidden, false);
  assert.equal(element('#create-task').querySelector('button').disabled, true);
  assert.equal(element('#tasks').children.length, 2);
  for (const row of element('#tasks').children) assert.equal(row.children[1].disabled, true);
  element('#task-title').value = 'Blocked';
  await element('#create-task').trigger('submit');
  await element('#tasks').children[0].children[1].trigger('change');
  assert.equal(writes, 0);
  element('#task-filter').value = 'completed';
  await element('#task-filter').trigger('change');
  assert.equal(element('#tasks').children.length, 1);
  assert.equal(element('#tasks').children[0].children[0].textContent, 'Done');
  assert.equal(element('#tasks').children[0].children[1].disabled, true);
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

async function launch(dbPath) {
  const child = spawn(process.execPath, ['server.js'], {
    env: { ...process.env, PORT: '0', DB_PATH: dbPath },
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  const url = await new Promise((resolve, reject) => {
    let output = '';
    let errors = '';
    child.stderr.on('data', (chunk) => { errors += chunk; });
    child.once('error', reject);
    child.once('exit', (code) => reject(new Error(`Server exited ${code}: ${errors}`)));
    child.stdout.on('data', (chunk) => {
      output += chunk;
      const match = output.match(/listening on port (\d+)/);
      if (match) resolve(`http://127.0.0.1:${match[1]}`);
    });
  });
  return {
    url,
    async stop() {
      const exited = once(child, 'exit');
      child.kill('SIGTERM');
      await exited;
    },
  };
}

test('launch contract, validation, creation order and process-restart persistence', { timeout: 15000 }, async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-'));
  let server;
  try {
    const path = join(directory, 'nested', 'projects.sqlite');
    server = await launch(path);
    const get = (route) => fetch(server.url + route);
    const create = (name) => fetch(server.url + '/api/projects', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name }),
    });
    const health = await get('/health');
    assert.equal(health.status, 200);
    assert.deepEqual(await health.json(), { status: 'ok' });
    const html = await (await get('/')).text();
    assert.match(html, /<h1>Workboard<\/h1>/);
    assert.match(html, /<label for="project-name">Project name<\/label>/);
    assert.match(html, />Create project<\/button>/);
    assert.deepEqual(await (await get('/api/projects')).json(), []);
    for (const name of ['', ' \t\n ', null, 123]) {
      const response = await create(name);
      assert.equal(response.status, 400);
      assert.deepEqual(await response.json(), { error: 'Project name is required' });
    }
    assert.deepEqual(await (await get('/api/projects')).json(), []);
    const firstResponse = await create('  First project \n');
    assert.equal(firstResponse.status, 201);
    const first = await firstResponse.json();
    assert.equal(first.name, 'First project');
    const second = await (await create('<script>not HTML</script>')).json();
    assert.notEqual(first.id, second.id);
    assert.deepEqual(await (await get('/api/projects')).json(), [first, second]);
    assert.deepEqual(await (await get(`/api/projects/${first.id}`)).json(), first);
    assert.equal((await get(`/projects/${first.id}`)).status, 200);
    assert.equal((await get('/api/projects/99999')).status, 404);
    const malformed = await fetch(server.url + '/api/projects', { method: 'POST', body: '{' });
    assert.equal(malformed.status, 400);
    await server.stop();
    server = undefined;
    server = await launch(path);
    assert.deepEqual(await (await get('/api/projects')).json(), [first, second]);
